INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (7, 1, -363, 7001, 0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (7, 1, -363, 7002, 0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (7, 1, -363, 7003, 0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10, 1, -363, 10001, 0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10, 1, -363, 10002, 0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10, 1, -363, 10003, 0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10, 2, -363, 10004, 0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (12, 1, -416.5, 12001, 0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13, 1, -363, 13001, 0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13, 1, -363, 13002, 0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13, 2, -363, 13003, 0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (13, 1, -363, 13004, 0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14, 1, -363, 14001, 0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14, 2, -363, 14002, 0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14, 1, -363, 14003, 0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (14, 1, -363, 14004, 0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (15, 1, -470, 15001, 0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16, 2, -363, 16001, 0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16, 1, -363, 16002, 0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16, 1, -363, 16003, 0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (16, 1, -363, 16004, 0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (17, 1, -363, 17002, 0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (25, 1, -363, 17004, 0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (25, 1, -363, 17005, 0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (25, 2, -363, 17006, 0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (25, 1, -363, 17007, 0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (18, 1, -363, 18001, 0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", "カリン", 1, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (18, 1, -363, 18002, 0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", "カリン", 2, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (19, 1, -470, 19001, 0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", "カリン", 3, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (19, 1, -470, 19002, 0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", "カリン", 4, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (20, 1, -470, 20001, 0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", "カリン", 5, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (20, 1, -470, 20002, 0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", "カリン", 6, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21, 1, -363, 21001, 0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21, 1, -363, 21002, 0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21, 2, -363, 21003, 0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (21, 1, -363, 21004, 0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (22, 1, -430, 22001, 0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", "カリン", 1, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (22, 1, -430, 22002, 0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", "カリン", 2, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (23, 1, -430, 23001, 0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", "カリン", 3, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (23, 1, -430, 23002, 0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", "カリン", 4, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, -385, 24001, 10011, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", "エリコ（バレンタイン）", 1, 109001, 0, 4.08, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, -385, 24002, 10011, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", "エリコ（バレンタイン）", 2, 109001, 0, 5, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, -385, 24003, 10011, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", "エリコ（バレンタイン）", 3, 109001, 0, 10.11, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, -385, 24004, 10011, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", "エリコ（バレンタイン）", 4, 109001, 0, 4, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, -385, 24005, 10011, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", "エリコ（バレンタイン）", 5, 109001, 0, 6, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24006, 10011, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", "エリコ（バレンタイン）", 6, 109002, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24007, 10011, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", "エリコ（バレンタイン）", 7, 109002, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24008, 10011, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", "エリコ（バレンタイン）", 8, 109002, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24009, 10011, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", "エリコ（バレンタイン）", 9, 109002, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24010, 10011, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", "エリコ（バレンタイン）", 10, 109002, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, -385, 24011, 10011, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", "シズル（バレンタイン）", 1, 109101, 0, 2.12, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 5, -385, 24012, 10011, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", "シズル（バレンタイン）", 2, 109101, 0, 4.19, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 2, -385, 24013, 10011, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", "シズル（バレンタイン）", 3, 109101, 0, 2.3, 4, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24014, 10011, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", "シズル（バレンタイン）", 4, 109102, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 5, -385, 24015, 10011, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", "シズル（バレンタイン）", 5, 109101, 0, 5.23, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24016, 10011, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", "シズル（バレンタイン）", 6, 109102, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, -385, 24017, 10011, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", "シズル（バレンタイン）", 7, 109101, 0, 5.01, 2, 8, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24018, 10011, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", "シズル（バレンタイン）", 8, 109102, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24019, 10011, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", "シズル（バレンタイン）", 9, 109102, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (24, 1, 0, 24020, 10011, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", "シズル（バレンタイン）", 10, 109102, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (26, 2, -363, 26001, 0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (26, 1, -363, 26002, 0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (26, 1, -363, 26003, 0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (26, 1, -363, 26004, 0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (27, 2, -363, 27001, 0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (27, 1, -363, 27002, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (27, 1, -363, 27003, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (27, 1, -363, 27004, 0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (28, 1, -363, 28001, 0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", "カリン", 1, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (28, 1, -363, 28002, 0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", "カリン", 2, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (29, 1, -409, 29001, 0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", "カリン", 3, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (29, 1, -409, 29002, 0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", "カリン", 4, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (30, 1, -409, 30001, 0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", "カリン", 5, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (30, 1, -409, 30002, 0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", "カリン", 6, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (31, 1, -409, 31001, 0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", "カリン", 7, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/10/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (31, 1, -409, 31002, 0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", "カリン", 8, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2019/10/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (32, 1, -409, 32001, 0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", "カリン", 1, 190801, 0, 0, 1, 0, "2020/01/04 4:59:59", "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (32, 1, -409, 32002, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "カリン", 2, 190801, 0, 0, 1, 0, "2020/01/04 4:59:59", "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (33, 1, -409, 33001, 0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", "カリン", 3, 190801, 0, 0, 1, 0, "2020/01/04 4:59:59", "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (33, 1, -409, 33002, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "カリン", 4, 190801, 0, 0, 1, 0, "2020/01/04 4:59:59", "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (34, 1, -409, 34001, 0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", "カリン", 5, 190801, 0, 0, 1, 0, "2020/01/10 11:59:59", "2020/01/04 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (34, 1, -409, 34002, 0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", "カリン", 6, 190801, 0, 0, 1, 0, "2020/01/10 11:59:59", "2020/01/04 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (38, 1, -458, 38001, 0, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", "ペコリーヌ", 1, 105801, 0, 5.3, 2, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (38, 1, -458, 38002, 0, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", "ペコリーヌ", 2, 105801, 0, 6.5, 2, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (39, 3, 9999, 39005, 0, "", "ペコリーヌ", 0, 105801, 0, 0, 3, 9999, "2020/04/08 23:59:59", "2020/04/01");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (40, 1, -430, 40001, 0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", "カリン", 2, 190801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (41, 1, -363, 41001, 0, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (41, 1, -363, 41002, 0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (41, 1, -363, 41003, 0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (41, 1, -363, 41004, 0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (42, 1, -416.5, 42001, 0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (42, 1, -416.5, 42002, 0, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", "シェフィ", 1, 106401, 2104010, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (42, 1, -416.5, 42003, 0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (42, 1, -416.5, 42004, 0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (43, 1, -363, 43001, 0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", "ペコリーヌ", 1, 105801, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (43, 1, -363, 43002, 0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", "コッコロ", 1, 105901, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (43, 1, -363, 43003, 0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", "キャル", 1, 106001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (44, 1, -416.5, 43004, 0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", "アメス", 1, 123001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (44, 1, -416.5, 43005, 0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", "アメス", 2, 123001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (45, 1, -416.5, 43006, 0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", "アメス", 3, 123001, 0, 5.79, 2, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (46, 1, -371.5, 46001, 0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", "アメス", 1, 123001, 0, 0, 1, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (47, 2, -416.5, 47001, 0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", "シズル", 1, 104901, 0, 0, 2, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (47, 1, -416.5, 47002, 0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", "リノ", 1, 101101, 0, 9.32, 2, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (48, 2, -470, 48001, 0, "", "シズル", 0, 104901, 0, 0, 2, 0, "2030/12/17 14:59:59", "2015/12/17 15:00:00");
